<template>
  <section class="knowledge-card" :data-layout="type">
    <header><span class="card-kicker">{{kindLabels[type]}}</span><h3>{{text(card.title,80)}}</h3><p v-if="card.intro">{{text(card.intro,240)}}</p></header>
    <dl v-if="type==='facts'" class="facts"><div v-for="(item,i) in items" :key="i" :class="{'fact-wide':text(item.value,20000).length>140}"><dt>{{text(item.label,500)}}</dt><dd>{{text(item.value,20000)}}</dd></div></dl>
    <div v-else-if="type==='compare'" class="compare-scroll"><table><thead><tr><th v-for="(col,i) in columns" :key="i" scope="col">{{col}}</th></tr></thead><tbody><tr v-for="(row,i) in rows" :key="i"><td v-for="(_,j) in columns" :key="j">{{row[j] || '未收录'}}</td></tr></tbody></table></div>
    <ol v-else-if="type==='timeline'" class="timeline"><li v-for="(item,i) in items" :key="i"><time>{{text(item.date,500)}}</time><div><strong>{{text(item.title,500)}}</strong><p>{{text(item.desc,20000)}}</p></div></li></ol>
    <ul v-else-if="type==='checklist'" class="checklist"><li v-for="(item,i) in items" :key="i"><label><input type="checkbox" :checked="checked.has(i)" @change="toggle(i)"/><span><strong>{{text(item.title || item.label,500)}}</strong><small>{{text(item.desc,20000)}}</small></span></label></li></ul>
    <ol v-else-if="type==='sources'" class="sources"><li v-for="(item,i) in items" :key="i"><span class="source-index">{{text(item.id,30) || i+1}}</span><div><a v-if="safeUrl(item.url)" :href="safeUrl(item.url)" target="_blank" rel="noopener noreferrer">{{text(item.title,160)}}</a><strong v-else>{{text(item.title,160)}}</strong><p>{{text(item.source,180)}}<span v-if="item.updatedAt"> · {{text(item.updatedAt,60)}}</span></p><small>{{text(item.note,300)}}</small></div></li></ol>
    <footer v-if="card.note">{{text(card.note,20000)}}</footer>
  </section>
</template>
<script setup lang="ts">
import {computed,reactive,watch} from 'vue'
const props=defineProps<{card:Record<string,unknown>}>()
const type=computed(()=>text(props.card.type,30))
const kindLabels:Record<string,string>={facts:'关键信息',compare:'方案比较',timeline:'时间安排',checklist:'准备清单',sources:'资料来源'}
function text(v:unknown,max=200){return typeof v==='string'?v.slice(0,max):typeof v==='number'?String(v):''}
function safeUrl(v:unknown){try{const u=new URL(text(v,1000));return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
const items=computed(()=>Array.isArray(props.card.items)?props.card.items.filter(v=>v && typeof v==='object' && !Array.isArray(v)) as Record<string,unknown>[]:[])
const columns=computed(()=>Array.isArray(props.card.columns)?props.card.columns.map(v=>text(v,500)).filter(Boolean):[])
const rows=computed(()=>Array.isArray(props.card.rows)?props.card.rows.filter(Array.isArray).map(row=>row.map(v=>text(v,20000))):[])
const checked=reactive(new Set<number>())
function toggle(i:number){checked.has(i)?checked.delete(i):checked.add(i)}
watch(()=>props.card,()=>checked.clear())
</script>
<style scoped>
.knowledge-card{color:var(--sc-ink,var(--el-text-color-primary));padding:22px;line-height:1.65}.card-kicker{font-size:11px;letter-spacing:2px;color:var(--sc-dai,var(--el-color-primary))}h3{font-size:19px;margin:7px 0 10px;font-weight:600}header>p{font-size:13px;color:var(--sc-muted,var(--el-text-color-secondary));margin:0 0 18px}.facts{margin:0;display:grid;grid-template-columns:1fr 1fr;gap:16px}.facts>div{border-top:1px solid var(--sc-line,var(--el-border-color));padding-top:12px}dt{font-size:12px;color:var(--sc-muted,var(--el-text-color-secondary))}dd{margin:4px 0 0;font-weight:500;white-space:pre-wrap}.compare-scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:360px;text-align:left;font-size:13px}th,td{padding:12px;border-bottom:1px solid var(--sc-line,var(--el-border-color));vertical-align:top}th{background:var(--sc-paper,var(--el-fill-color-light));font-weight:600}.timeline,.checklist,.sources{list-style:none;padding:0;margin:0}.timeline li{display:flex;gap:18px;border-left:2px solid var(--sc-line,var(--el-border-color));padding:0 0 20px 16px}.timeline time{min-width:70px;font-size:12px;color:var(--sc-dai,var(--el-color-primary))}.timeline p{margin:5px 0 0;font-size:13px}.checklist li{padding:12px 0;border-bottom:1px solid var(--sc-line,var(--el-border-color))}.checklist label{display:flex;gap:12px;align-items:flex-start;cursor:pointer}.checklist input{margin-top:5px;accent-color:var(--sc-dai,var(--el-color-primary))}.checklist small{display:block;color:var(--sc-muted,var(--el-text-color-secondary));font-size:12px;white-space:pre-wrap}.sources li{display:flex;gap:14px;margin:0 0 18px}.source-index{min-width:28px;font-size:12px;font-variant-numeric:tabular-nums;color:var(--sc-dai,var(--el-color-primary))}.sources a{color:var(--sc-dai,var(--el-color-primary));text-decoration:underline;text-underline-offset:3px}.sources p,.sources small{margin:4px 0;font-size:12px;color:var(--sc-muted,var(--el-text-color-secondary))}footer{margin-top:18px;padding-top:14px;border-top:1px solid var(--sc-line,var(--el-border-color));font-size:12px;color:var(--sc-muted,var(--el-text-color-secondary))}@media(max-width:480px){.knowledge-card{padding:16px}.facts{grid-template-columns:1fr}.timeline li{gap:10px}.timeline time{min-width:55px}}
</style>
<style scoped>
.knowledge-card{border:1px solid var(--nx-border,var(--el-border-color));border-radius:16px;background:var(--nx-surface,var(--el-bg-color));max-width:100%;min-width:0;box-sizing:border-box;overflow:hidden}.knowledge-card header{margin-bottom:18px}.knowledge-card h3{font-size:17px;line-height:1.6;overflow-wrap:anywhere}.facts{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.facts>div{padding:13px 14px;border:1px solid var(--nx-border,var(--el-border-color));border-radius:10px;background:var(--nx-surface-2,var(--el-fill-color-light));min-width:0}dt{font-size:11px}dd{font-size:13px;line-height:1.8;overflow-wrap:anywhere}.compare-scroll{border:1px solid var(--nx-border,var(--el-border-color));border-radius:10px}table{min-width:320px}td,th{overflow-wrap:anywhere;min-width:90px}.timeline li{position:relative;padding-bottom:22px}.timeline li::before{content:'';position:absolute;left:-5px;top:5px;width:8px;height:8px;border-radius:50%;background:var(--nx-accent,var(--el-color-primary));box-shadow:0 0 0 3px var(--nx-surface,var(--el-bg-color))}.timeline time{max-width:110px;overflow-wrap:anywhere}.timeline li>div{min-width:0;overflow-wrap:anywhere}.checklist strong{font-size:13px}.checklist li:last-child{border-bottom:0}.checklist input{width:15px;height:15px;flex-shrink:0}.checklist label:has(input:checked) strong{color:var(--nx-text-3,var(--el-text-color-secondary));text-decoration:line-through}@media(max-width:600px){.knowledge-card{padding:16px}.facts{grid-template-columns:minmax(0,1fr)}.facts>div{padding:12px}}
.facts>.fact-wide{grid-column:1/-1}
</style>
